{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection Vulnerability",
      "severity": "High",
      "file": "AccountSearchController.cls",
      "lines": "6",
      "explanation": "The searchAccounts method constructs a SOQL query by concatenating the user-provided searchKey directly into the query string without any sanitization or binding. This allows an attacker to inject malicious SOQL syntax and potentially access unauthorized data.",
      "remediation": "Replace the dynamic query construction with a bind variable approach: 'SELECT Id, Name, Industry FROM Account WHERE Name LIKE :searchKey LIMIT 50'. Remove the AccessLevel.USER_MODE parameter as it's not needed for this type of query."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "FLS violation on Opportunity.Amount field",
      "severity": "Medium",
      "file": "Opportunity_Stage_Editor.permissionset-meta.xml",
      "lines": "fieldPermissions",
      "explanation": "The permission set grants read access to Opportunity.Amount but not edit access. However, the Apex class attempts to update the StageName field which is editable, but the Amount field is also selected in the query and potentially accessible to the caller. This could lead to unauthorized data exposure if the Amount field were to be modified in a future version.",
      "remediation": "Ensure that all fields accessed or modified by the Apex class are properly controlled through field permissions in the permission set, matching the actual usage in the code."
    },
    {
      "category": "C3",
      "title": "Missing sharing enforcement on OpportunityStageService",
      "severity": "Medium",
      "file": "OpportunityStageService.cls",
      "lines": "public with sharing class",
      "explanation": "While the class is declared with 'with sharing', it's important to note that the @AuraEnabled method is accessible from external contexts. The class should ensure that record-level sharing is enforced when accessed externally.",
      "remediation": "Verify that all methods accessible via @AuraEnabled or other external entry points enforce proper sharing rules and consider using 'inherited sharing' if appropriate."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Missing sharing enforcement in Aura-enabled controller",
      "severity": "High",
      "file": "CaseHistoryController.cls",
      "lines": "7",
      "explanation": "The class is declared 'without sharing' and is reachable via @AuraEnabled, making it accessible to external users. This bypasses record-level sharing rules, allowing users to potentially access cases they shouldn't be able to see based on their sharing settings.",
      "remediation": "Change the class declaration from 'without sharing' to 'with sharing' or 'inherited sharing' to enforce record-level sharing rules."
    },
    {
      "category": "C2",
      "title": "FLS not properly enforced after stripInaccessible",
      "severity": "Medium",
      "file": "CaseHistoryController.cls",
      "lines": "7",
      "explanation": "While Security.stripInaccessible is used, the code does not ensure that all fields accessed afterward are properly sanitized or validated. The FLS violation warning indicates that Salesforce cannot verify that only sanitized data is used after the check.",
      "remediation": "Ensure that all data returned from stripInaccessible is validated and that field-level security is explicitly checked before any further processing."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive permissions in Support Agent Tools permission set",
      "severity": "High",
      "file": "Support_Agent_Tools.permissionset-meta.xml",
      "lines": "15, 16, 17, 18",
      "explanation": "The Support Agent Tools permission set grants ModifyAllData, ViewAllData, AuthorApex, and ApiEnabled permissions. These are powerful system permissions that should only be granted to administrators or integration users with a clear need. The description indicates it's for 'tier-1 support agents', which doesn't justify such broad access.",
      "remediation": "Remove the ModifyAllData, ViewAllData, AuthorApex, and ApiEnabled permissions from the Support Agent Tools permission set. Only grant the minimal permissions needed for tier-1 support agents to view and close cases."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "FLS violation on Product2.Family field",
      "severity": "Medium",
      "file": "Catalog Site Profile.profile-meta.xml",
      "lines": "fieldPermissions",
      "explanation": "The profile grants read access to the Product2.Family field but does not grant editable access. However, the Apex class PublicCatalogController retrieves this field in a query without enforcing FLS. Even though the field is readable, the code doesn't strip inaccessible fields, which could lead to unexpected behavior or data exposure if the field permissions change.",
      "remediation": "Use Security.stripInaccessible() after the SOQL query to ensure that only accessible fields are returned to the caller, or enforce FLS by using WITH SECURITY_ENFORCED in the SOQL query."
    },
    {
      "category": "C5",
      "title": "Guest user profile exposes sensitive data",
      "severity": "High",
      "file": "Catalog Site Profile.profile-meta.xml",
      "lines": "userLicense",
      "explanation": "The profile uses 'Guest User License', indicating unauthenticated users can access the system. The PublicCatalogController class is enabled for this profile and returns Product2 records, which may contain sensitive information. Since the class is @AuraEnabled and reachable by guest users, it could expose data to unauthorized parties.",
      "remediation": "Restrict access to the PublicCatalogController class from guest profiles or ensure that only non-sensitive fields are returned. Consider using a separate profile for public access with minimal permissions."
    }
  ]
}
